shapes={}
for c in [1,2,4,6,8]:
    lab,n=label(a==c)
    for i in range(1,n+1):
        cells=[(int(y),int(x)) for y,x in zip(*np.where(lab==i))]
        shapes.setdefault(c,[]).append(cells)
def norm(cells):
    ys=[y for y,x in cells]; xs=[x for y,x in cells]
    my,mx=min(ys),min(xs)
    return tuple(sorted((y-my,x-mx) for y,x in cells))
ones=shapes[1]; others=[(c,cells) for c in [2,4,6,8] for cells in shapes[c]]
